css:
@property --fxh-beam-aim-a { syntax: "<angle>"; inherits: true; initial-value: 0deg; }
@property --fxh-beam-aim-w { syntax: "<angle>"; inherits: true; initial-value: 68deg; }
@property --fxh-beam-aim-k { syntax: "<number>"; inherits: true; initial-value: 0.8; }

.fxh-beam-aim {
  --fxh-beam-aim-bg: oklch(17% 0.012 60);
  --fxh-beam-aim-ink: oklch(94.5% 0.014 80);
  --fxh-beam-aim-beam: oklch(79% 0.15 64);
  --fxh-beam-aim-hot: oklch(97% 0.05 95);
  --fxh-beam-aim-surface: color-mix(in oklch, var(--fxh-beam-aim-ink) 4%, var(--fxh-beam-aim-bg));
  --fxh-beam-aim-line: color-mix(in oklch, var(--fxh-beam-aim-ink) 12%, var(--fxh-beam-aim-bg));
  --fxh-beam-aim-muted: color-mix(in oklch, var(--fxh-beam-aim-ink) 60%, var(--fxh-beam-aim-bg));
  --fxh-beam-aim-ease: cubic-bezier(.2, .8, .2, 1);
  --fxh-beam-aim-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  container-name: fxh-beam-aim;
  container-type: inline-size;
  position: relative;
  isolation: isolate;
  box-sizing: border-box;
  width: 100%;
  max-width: 420px;
  margin-inline: auto;
  padding: 12px;
  color: var(--fxh-beam-aim-ink);
  font: 400 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  animation: fxh-beam-aim-orbit 9s linear infinite;
  transition: --fxh-beam-aim-w .55s var(--fxh-beam-aim-ease), --fxh-beam-aim-k .55s var(--fxh-beam-aim-ease);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h3, p, ul) { margin: 0; padding: 0; }
  &.is-aim { animation: none; }
  &.is-off { animation-play-state: paused; }
}
@keyframes fxh-beam-aim-orbit { from { --fxh-beam-aim-a: 0deg; } to { --fxh-beam-aim-a: 360deg; } }

/* the glow outside the edge: the same wedge, blurred, behind the card */
.fxh-beam-aim-bloom {
  position: absolute;
  inset: 12px;
  z-index: -1;
  border-radius: 20px;
  background: conic-gradient(from calc(var(--fxh-beam-aim-a) - var(--fxh-beam-aim-w) / 2),
    transparent, var(--fxh-beam-aim-beam) calc(var(--fxh-beam-aim-w) * .5), transparent var(--fxh-beam-aim-w));
  filter: blur(16px);
  opacity: calc(var(--fxh-beam-aim-k) * .75);
}

.fxh-beam-aim-card {
  /* where the beam meets the edge, in pure CSS trig, so the inner spill follows the orbit too */
  --fxh-beam-aim-sx: calc(50% + sin(var(--fxh-beam-aim-a)) * 52%);
  --fxh-beam-aim-sy: calc(50% - cos(var(--fxh-beam-aim-a)) * 52%);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "head head" "title title" "price switch" "specs specs" "cta cta";
  align-items: end;
  gap: 10px 12px;
  padding: clamp(16px, 5.8cqi, 22px);
  border: 2px solid transparent;
  border-radius: 20px;
  background:
    radial-gradient(75% 60% at var(--fxh-beam-aim-sx) var(--fxh-beam-aim-sy),
      color-mix(in oklch, var(--fxh-beam-aim-beam) calc(var(--fxh-beam-aim-k) * 14%), transparent), transparent) padding-box,
    linear-gradient(var(--fxh-beam-aim-surface), var(--fxh-beam-aim-surface)) padding-box,
    conic-gradient(from calc(var(--fxh-beam-aim-a) - var(--fxh-beam-aim-w) / 2),
      transparent,
      color-mix(in oklch, var(--fxh-beam-aim-beam) calc(var(--fxh-beam-aim-k) * 100%), transparent) calc(var(--fxh-beam-aim-w) * .3),
      color-mix(in oklch, var(--fxh-beam-aim-hot) calc(var(--fxh-beam-aim-k) * 100%), transparent) calc(var(--fxh-beam-aim-w) * .5),
      color-mix(in oklch, var(--fxh-beam-aim-beam) calc(var(--fxh-beam-aim-k) * 100%), transparent) calc(var(--fxh-beam-aim-w) * .7),
      transparent var(--fxh-beam-aim-w)) border-box,
    linear-gradient(var(--fxh-beam-aim-line), var(--fxh-beam-aim-line)) border-box;
  box-shadow: 0 28px 56px -28px oklch(0% 0 0 / .7);
}
.fxh-beam-aim-card.is-flash, .fxh-beam-aim-bloom.is-flash { animation: fxh-beam-aim-flash 1.15s var(--fxh-beam-aim-ease); }
@keyframes fxh-beam-aim-flash { 38% { --fxh-beam-aim-w: 360deg; --fxh-beam-aim-k: 1; } }

.fxh-beam-aim-head { grid-area: head; display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.fxh-beam-aim-brand {
  display: inline-flex; align-items: center; gap: 8px; min-width: 0; white-space: nowrap;
  font-weight: 600; font-size: 12.5px; letter-spacing: .01em;
  & svg { width: 18px; height: 18px; fill: none; stroke: var(--fxh-beam-aim-beam); stroke-width: 1.6; stroke-linejoin: round; stroke-linecap: round; }
}
.fxh-beam-aim-tag {
  flex: none; white-space: nowrap; padding: 5px 8px; border: 1px solid var(--fxh-beam-aim-line); border-radius: 99px;
  font: 500 10.5px/1 ui-monospace, Menlo, monospace; letter-spacing: .1em; text-transform: uppercase;
  color: var(--fxh-beam-aim-muted);
}
.fxh-beam-aim-title { grid-area: title; margin-top: 2px; font-size: clamp(22px, 8cqi, 30px); font-weight: 700; line-height: 1.05; letter-spacing: -.03em; text-wrap: balance; }
.fxh-beam-aim-price { grid-area: price; min-width: 0; }
.fxh-beam-aim-amt { display: flex; align-items: baseline; gap: 6px; font-variant-numeric: tabular-nums; }
.fxh-beam-aim-num { display: inline-block; font-size: clamp(30px, 11cqi, 40px); font-weight: 650; line-height: 1; letter-spacing: -.035em; }
.fxh-beam-aim-per { color: var(--fxh-beam-aim-muted); font-size: 13px; }
.fxh-beam-aim-sub { margin-top: 6px; color: var(--fxh-beam-aim-muted); font-size: 12px; font-variant-numeric: tabular-nums; text-wrap: pretty; }

.fxh-beam-aim-switch {
  grid-area: switch; justify-self: end;
  appearance: none; display: inline-flex; align-items: center; gap: 8px;
  padding: 6px 11px 6px 6px; border: 1px solid var(--fxh-beam-aim-line); border-radius: 99px;
  background: transparent; color: var(--fxh-beam-aim-ink); font: 550 12px/1 system-ui, sans-serif; cursor: pointer;
  transition: border-color .25s;
  &:hover { border-color: color-mix(in oklch, var(--fxh-beam-aim-beam) 50%, var(--fxh-beam-aim-line)); }
  & em { font-style: normal; color: var(--fxh-beam-aim-beam); font-variant-numeric: tabular-nums; }
}
.fxh-beam-aim-knob {
  position: relative; width: 28px; height: 16px; border-radius: 99px; background: var(--fxh-beam-aim-line);
  transition: background-color .3s var(--fxh-beam-aim-ease);
  &::after { content: ""; position: absolute; top: 2px; left: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--fxh-beam-aim-ink); transition: translate .5s var(--fxh-beam-aim-spring), background-color .3s; }
}
.fxh-beam-aim-switch[aria-checked="true"] .fxh-beam-aim-knob {
  background: var(--fxh-beam-aim-beam);
  &::after { translate: 12px 0; background: var(--fxh-beam-aim-bg); }
}

.fxh-beam-aim-specs {
  grid-area: specs; list-style: none; display: grid; gap: 8px; padding-block: 12px;
  border-block: 1px solid var(--fxh-beam-aim-line); font-size: 13px; color: color-mix(in oklch, var(--fxh-beam-aim-ink) 82%, var(--fxh-beam-aim-bg));
  & li { display: grid; grid-template-columns: 18px minmax(0, 1fr); align-items: center; gap: 10px; }
  & svg { width: 18px; height: 18px; fill: none; stroke: var(--fxh-beam-aim-muted); stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & b { font-weight: 600; color: var(--fxh-beam-aim-ink); font-variant-numeric: tabular-nums; }
}

.fxh-beam-aim-cta {
  grid-area: cta; appearance: none; display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  height: 42px; border: 0; border-radius: 12px; cursor: pointer;
  background: var(--fxh-beam-aim-beam); color: var(--fxh-beam-aim-bg); font: 650 14px/1 system-ui, sans-serif;
  transition: transform .45s var(--fxh-beam-aim-spring), background-color .3s, color .3s, box-shadow .3s;
  &:hover { background: color-mix(in oklch, var(--fxh-beam-aim-beam), var(--fxh-beam-aim-hot) 28%); }
  &:active { transform: scale(.975); }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  & .fxh-beam-aim-arrow { transition: transform .4s var(--fxh-beam-aim-spring), opacity .2s; }
  & .fxh-beam-aim-tick { stroke-dasharray: 20; stroke-dashoffset: 20; transition: stroke-dashoffset .45s .08s var(--fxh-beam-aim-ease); }
  &:hover .fxh-beam-aim-arrow { transform: translateX(2px); }
  &[aria-pressed="true"] {
    background: transparent; color: var(--fxh-beam-aim-ink);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--fxh-beam-aim-beam) 55%, var(--fxh-beam-aim-line));
    & .fxh-beam-aim-arrow { opacity: 0; transform: translateX(-4px); }
    & .fxh-beam-aim-tick { stroke-dashoffset: 0; stroke: var(--fxh-beam-aim-beam); }
  }
}
.fxh-beam-aim :is(button):focus-visible { outline: 2px solid var(--fxh-beam-aim-hot); outline-offset: 3px; }

@container fxh-beam-aim (max-width: 330px) {
  .fxh-beam-aim-card { grid-template-columns: minmax(0, 1fr); grid-template-areas: "head" "title" "price" "switch" "specs" "cta"; gap: 10px; }
  .fxh-beam-aim-switch { justify-self: start; }
  .fxh-beam-aim-specs { gap: 6px; padding-block: 10px; font-size: 12.5px; }
}
@container fxh-beam-aim (max-width: 240px) {
  .fxh-beam-aim-card { padding: 14px; }
  .fxh-beam-aim-specs li:nth-child(3) { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .fxh-beam-aim { animation: none; transition: none; --fxh-beam-aim-a: 315deg; }
  .fxh-beam-aim-card.is-flash, .fxh-beam-aim-bloom.is-flash { animation: none; }
  .fxh-beam-aim-cta, .fxh-beam-aim-knob, .fxh-beam-aim-knob::after, .fxh-beam-aim-cta .fxh-beam-aim-arrow, .fxh-beam-aim-cta .fxh-beam-aim-tick { transition: none; }
}

