const card = root.querySelector('.fxh-beam-aim-card');
const bloom = root.querySelector('.fxh-beam-aim-bloom');
const sw = root.querySelector('.fxh-beam-aim-switch');
const cta = root.querySelector('.fxh-beam-aim-cta');
const num = root.querySelector('.fxh-beam-aim-num');
const sub = root.querySelector('.fxh-beam-aim-sub');
const lbl = root.querySelector('.fxh-beam-aim-lbl');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const ORBIT = 9000;

/* The beam angle is a registered <angle>. At rest a CSS animation orbits it; while the
   pointer is near, a spring in JS owns it and aims it at the pointer's bearing from the
   card centre. Hand-off in both directions is seamless: JS starts from the computed
   animated value, and the orbit resumes with a negative delay at wherever the spring left it. */
let cur = 0, vel = 0, target = 0, raf = 0, last = 0, aiming = false, pending = null;

function readAngle() {
  const v = parseFloat(getComputedStyle(root).getPropertyValue('--fxh-beam-aim-a'));
  return Number.isFinite(v) ? v : 0;
}
function engage() {
  if (aiming) return;
  aiming = true;
  if (!root.classList.contains('is-aim')) {
    cur = target = readAngle(); vel = 0;
    root.style.setProperty('--fxh-beam-aim-a', cur.toFixed(2) + 'deg');
    root.classList.add('is-aim');
  }
}
function release() {
  aiming = false;
  root.style.removeProperty('--fxh-beam-aim-w');
  root.style.removeProperty('--fxh-beam-aim-k');
  kick();
}
/* one rect read per frame, then writes only */
function aimAt(x, y) {
  const r = card.getBoundingClientRect();
  const hw = r.width / 2, hh = r.height / 2;
  const dx = x - (r.left + hw), dy = y - (r.top + hh);
  const t = Math.atan2(dx, -dy) * 180 / Math.PI;
  target = cur + ((((t - cur) % 360) + 540) % 360) - 180;   /* shortest way round */
  const n = Math.max(Math.abs(dx) / hw, Math.abs(dy) / hh);  /* 0 centre, 1 on the edge */
  const w = 118 - Math.min(n, 1) * 74;                        /* wide and soft inside, tight at the edge */
  const k = n <= 1 ? 0.5 + n * 0.5 : Math.max(0.3, 1 - (n - 1) * 2.2);
  root.style.setProperty('--fxh-beam-aim-w', w.toFixed(1) + 'deg');
  root.style.setProperty('--fxh-beam-aim-k', k.toFixed(3));
}
function handBack() {
  if (reduce.matches) return;
  const a = ((cur % 360) + 360) % 360;
  root.style.animationDelay = (-a / 360 * ORBIT).toFixed(0) + 'ms';
  root.style.removeProperty('--fxh-beam-aim-a');
  root.classList.remove('is-aim');
}
function tick(now) {
  if (!root.isConnected) return;
  raf = 0;
  const dt = Math.min(0.034, Math.max(0.004, (now - last) / 1000)); last = now;
  if (pending) { aimAt(pending.x, pending.y); pending = null; }
  if (reduce.matches) { cur += (target - cur) * 0.3; vel = 0; }
  else { vel += (170 * (target - cur) - 17 * vel) * dt; cur += vel * dt; }
  root.style.setProperty('--fxh-beam-aim-a', cur.toFixed(2) + 'deg');
  if (Math.abs(target - cur) > 0.05 || Math.abs(vel) > 0.4) { raf = requestAnimationFrame(tick); return; }
  cur = target;
  if (!aiming) handBack();
}
function kick() { if (!raf) { last = performance.now(); raf = requestAnimationFrame(tick); } }

function point(e) { engage(); pending = { x: e.clientX, y: e.clientY }; kick(); }
root.addEventListener('pointermove', point);
root.addEventListener('pointerdown', point);
root.addEventListener('pointerleave', release);

/* keyboard users get the same light: aim at whatever is focused */
root.addEventListener('focusin', (e) => {
  let fv = false; try { fv = e.target.matches(':focus-visible'); } catch (_) {}
  if (!fv) return;
  const r = e.target.getBoundingClientRect();
  engage(); pending = { x: r.left + r.width / 2, y: r.top + r.height / 2 }; kick();
});
root.addEventListener('focusout', (e) => { if (!root.contains(e.relatedTarget)) release(); });

sw.addEventListener('click', () => {
  const on = sw.getAttribute('aria-checked') !== 'true';
  sw.setAttribute('aria-checked', String(on));
  const k = on ? 'y' : 'm';
  num.textContent = num.dataset[k];
  sub.textContent = sub.dataset[k];
  if (!reduce.matches && num.animate) {
    num.animate([{ opacity: 0, transform: 'translateY(.32em)', filter: 'blur(4px)' }, { opacity: 1, transform: 'none', filter: 'blur(0)' }],
      { duration: 520, easing: 'cubic-bezier(.2,.8,.2,1)' });
  }
});

cta.addEventListener('click', () => {
  const on = cta.getAttribute('aria-pressed') !== 'true';
  cta.setAttribute('aria-pressed', String(on));
  lbl.textContent = on ? 'Held for 24 h' : 'Reserve nodes';
  if (on && !reduce.matches) {
    [card, bloom].forEach((el) => { el.classList.remove('is-flash'); void el.offsetWidth; el.classList.add('is-flash'); });
  }
});
[card, bloom].forEach((el) => el.addEventListener('animationend', (e) => {
  if (e.animationName === 'fxh-beam-aim-flash') el.classList.remove('is-flash');
}));

/* the orbit is a CSS animation; park it while the card is off screen */
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  root.classList.toggle('is-off', !es[es.length - 1].isIntersecting);
});
io.observe(root);

css:
.fxh-pluck {
  --fxh-pluck-paper: oklch(96.5% 0.014 85);
  --fxh-pluck-ink: oklch(22% 0.018 50);
  --fxh-pluck-accent: oklch(60% 0.19 33);
  --fxh-pluck-rule: color-mix(in oklch, var(--fxh-pluck-ink) 24%, var(--fxh-pluck-paper));
  --fxh-pluck-muted: color-mix(in oklch, var(--fxh-pluck-ink) 56%, var(--fxh-pluck-paper));
  --fxh-pluck-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  container-name: fxh-pluck;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  max-width: 460px;
  margin-inline: auto;
  padding: clamp(16px, 6cqi, 24px) clamp(16px, 6cqi, 24px) 14px;
  border-radius: 16px;
  background: var(--fxh-pluck-paper);
  color: var(--fxh-pluck-ink);
  font: 400 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h3, p, ol) { margin: 0; padding: 0; }
}
.fxh-pluck-head { padding-bottom: 12px; border-bottom: 2px solid var(--fxh-pluck-ink); }
.fxh-pluck-kicker {
  display: flex; justify-content: space-between; gap: 8px; flex-wrap: wrap;
  font-size: 10.5px; font-weight: 650; letter-spacing: .14em; text-transform: uppercase;
  & span { font-weight: 500; letter-spacing: .08em; color: var(--fxh-pluck-muted); font-variant-numeric: tabular-nums; }
}
.fxh-pluck-title {
  margin-top: 6px;
  font: 600 clamp(24px, 8.4cqi, 30px)/1 ui-serif, "New York", Georgia, serif;
  letter-spacing: -.02em; text-wrap: balance;
}

/* one column track set for the whole list; every row and link subgrids onto it */
.fxh-pluck-list {
  position: relative;
  list-style: none;
  display: grid;
  grid-template-columns: [no] 2.1em [name] minmax(0, 1fr) [pg] auto;
}
.fxh-pluck-row {
  position: relative;
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: subgrid;
}
.fxh-pluck-link {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: subgrid;
  grid-template-rows: auto auto;
  column-gap: 0;
  align-items: baseline;
  padding: 8px 0 9px;
  color: inherit;
  text-decoration: none;
  outline: none;
  transition: opacity .35s ease-out;
}
.fxh-pluck-no {
  grid-column: no; grid-row: 1 / span 2; align-self: start; padding-top: 3px;
  font: 500 11px/1 ui-monospace, Menlo, monospace; color: var(--fxh-pluck-muted); font-variant-numeric: tabular-nums;
  transition: color .25s;
}
.fxh-pluck-name {
  grid-column: name;
  font: 500 clamp(14.5px, 5cqi, 17.5px)/1.18 ui-serif, "New York", Georgia, serif;
  letter-spacing: -.01em; text-wrap: balance;
  transition: translate .55s var(--fxh-pluck-spring), color .25s;
}
.fxh-pluck-by {
  grid-column: name; margin-top: 1px;
  font-size: 11.5px; color: var(--fxh-pluck-muted); letter-spacing: .01em;
  transition: translate .55s 30ms var(--fxh-pluck-spring);
}
.fxh-pluck-pg {
  grid-column: pg; grid-row: 1 / span 2; align-self: center; padding-left: 12px;
  font: 500 12px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; color: var(--fxh-pluck-muted);
  transition: color .25s;
}
.fxh-pluck-vh { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* the string: an SVG rule that the script deforms and lets ring */
.fxh-pluck-string {
  --fxh-pluck-e: 0;
  position: absolute; left: 0; bottom: -12px;
  width: 100%; height: 24px; overflow: visible; pointer-events: none;
  & path {
    fill: none;
    stroke: color-mix(in oklch, var(--fxh-pluck-accent) calc(var(--fxh-pluck-e) * 100%), var(--fxh-pluck-rule));
    stroke-width: calc(1px + var(--fxh-pluck-e) * .6px);
    stroke-linecap: round;
  }
}

/* parent state with :has() — the rest of the list recedes while one row is under the pointer */
.fxh-pluck-list:has(.fxh-pluck-link:is(:hover, :focus-visible)) .fxh-pluck-link:not(:hover, :focus-visible) { opacity: .5; }
.fxh-pluck-link:is(:hover, :focus-visible) {
  & .fxh-pluck-name { translate: 6px 0; }
  & .fxh-pluck-by { translate: 6px 0; }
  & .fxh-pluck-no, & .fxh-pluck-pg { color: var(--fxh-pluck-accent); }
}
.fxh-pluck-link:focus-visible .fxh-pluck-name { text-decoration: underline 2px var(--fxh-pluck-accent); text-underline-offset: 4px; }
.fxh-pluck-name::before {
  content: ""; display: inline-block; width: 0; height: .42em; margin-right: 0; border-radius: 99px;
  background: var(--fxh-pluck-accent); vertical-align: .12em; scale: 0;
  transition: scale .5s var(--fxh-pluck-spring), width .5s var(--fxh-pluck-spring), margin-right .5s var(--fxh-pluck-spring);
}
.fxh-pluck-link[aria-current="true"] {
  & .fxh-pluck-no { color: var(--fxh-pluck-accent); font-weight: 700; }
  & .fxh-pluck-name { color: var(--fxh-pluck-accent); }
  & .fxh-pluck-name::before { width: .42em; margin-right: .38em; scale: 1; }
}

.fxh-pluck-foot {
  display: flex; justify-content: space-between; margin-top: 14px;
  font: 500 10.5px/1 ui-monospace, Menlo, monospace; letter-spacing: .08em; text-transform: uppercase; color: var(--fxh-pluck-muted);
}

@container fxh-pluck (max-width: 300px) {
