const list = root.querySelector('.fxh-pluck-list');
const links = [...root.querySelectorAll('.fxh-pluck-link')];
const reduce = matchMedia('(prefers-reduced-motion: reduce)');

/* Each rule is an ideal string: N nodes, ends pinned, integrated with the exact
   (Courant = 1) leapfrog scheme, so a pluck splits into two kinks that travel,
   reflect and decay instead of a canned wobble. */
const N = 44, BAND = 11, AMP = 10, STEPS = 3, DAMP = 0.9925, MID = 12;
const strings = [...root.querySelectorAll('.fxh-pluck-string')].map((svg) => ({
  svg, path: svg.querySelector('path'), li: svg.parentElement,
  y: new Float32Array(N), p: new Float32Array(N), n: new Float32Array(N),
  held: -1, live: false, rest: 0, w: 300, e: 0
}));
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
let ptr = null, raf = 0;

function draw(s) {
  const y = s.y, dx = s.w / (N - 1);
  let d = 'M0 ' + MID;
  for (let i = 1; i < N - 1; i++) {
    const x = i * dx;
    d += ' Q' + x.toFixed(1) + ' ' + (MID + y[i]).toFixed(2) + ' ' + (x + dx / 2).toFixed(1) + ' ' + (MID + (y[i] + y[i + 1]) / 2).toFixed(2);
  }
  d += ' L' + s.w.toFixed(1) + ' ' + MID;
  s.path.setAttribute('d', d);
  s.svg.style.setProperty('--fxh-pluck-e', Math.min(1, s.e / 2.2).toFixed(3));
}
function layout() {
  for (const s of strings) {
    s.w = Math.max(40, s.svg.clientWidth || list.clientWidth);
    s.rest = s.li.offsetTop + s.li.offsetHeight;    /* the string sits on the row's bottom edge */
    s.svg.setAttribute('viewBox', '0 0 ' + s.w.toFixed(1) + ' 24');
    draw(s);
  }
}
/* a held string is a straight-sided triangle to the pick point, as a real one is */
function shape(s, j, amp) {
  const y = s.y;
  for (let i = 0; i < N; i++) y[i] = i <= j ? amp * i / j : amp * (N - 1 - i) / (N - 1 - j);
  s.e = Math.abs(amp) / 2;
}
function step(s) {
  for (let k = 0; k < STEPS; k++) {
    const y = s.y, p = s.p, n = s.n;
    for (let i = 1; i < N - 1; i++) n[i] = (y[i + 1] + y[i - 1] - p[i]) * DAMP;
    n[0] = 0; n[N - 1] = 0;
    s.p = y; s.y = n; s.n = p;
  }
  let e = 0, m = 0;
  for (let i = 0; i < N; i++) { const a = Math.abs(s.y[i]); e += a; if (a > m) m = a; }
  s.e = e / N * 2;
  if (m < 0.06) { s.y.fill(0); s.p.fill(0); s.e = 0; s.live = false; }
}
function tick() {
  if (!root.isConnected) return;
  raf = 0;
  let lx = -1, ly = -1e9;
  if (ptr) { const r = list.getBoundingClientRect(); lx = ptr.x - r.left; ly = ptr.y - r.top; }
  let any = false;
  for (const s of strings) {
    const dy = ly - s.rest;
    if (ptr && Math.abs(dy) < BAND && lx > 2 && lx < s.w - 2) {
      shape(s, clamp(Math.round(lx / s.w * (N - 1)), 1, N - 2), clamp(dy, -AMP, AMP));
      s.held = 1; s.live = true;
    } else if (s.held > 0) {
      s.held = -1; s.p.set(s.y);   /* let go from rest: zero velocity, all potential */
    }
    if (s.live && s.held < 0) { step(s); if (!s.live) draw(s); }
    if (s.live || s.held > 0) { draw(s); any = true; }
  }
  if (any) raf = requestAnimationFrame(tick);
}
function kick() { if (!raf && !reduce.matches) raf = requestAnimationFrame(tick); }
function pluck(i, frac, amp) {
  const s = strings[i];
  if (!s || reduce.matches) return;
  shape(s, clamp(Math.round(frac * (N - 1)), 1, N - 2), amp);
  s.p.set(s.y); s.held = -1; s.live = true;
  kick();
}

list.addEventListener('pointermove', (e) => {
  if (e.pointerType === 'touch') return;
  ptr = { x: e.clientX, y: e.clientY }; kick();
});
list.addEventListener('pointerleave', () => { ptr = null; kick(); });
/* touch cannot hover: a tap plucks the nearest string where the finger landed */
list.addEventListener('pointerdown', (e) => {
  if (e.pointerType !== 'touch') return;
  const r = list.getBoundingClientRect(), y = e.clientY - r.top;
  let best = 0, bd = 1e9;
  strings.forEach((s, i) => { const d = Math.abs(y - s.rest); if (d < bd) { bd = d; best = i; } });
  pluck(best, (e.clientX - r.left) / r.width, y < strings[best].rest ? -AMP : AMP);
});

/* keyboard: arrows walk the list, focus plucks lightly, Enter marks the essay as current */
list.addEventListener('keydown', (e) => {
  const i = links.indexOf(e.target);
  if (i < 0) return;
  let j = -1;
  if (e.key === 'ArrowDown') j = (i + 1) % links.length;
  else if (e.key === 'ArrowUp') j = (i - 1 + links.length) % links.length;
  else if (e.key === 'Home') j = 0;
  else if (e.key === 'End') j = links.length - 1;
  if (j < 0) return;
  e.preventDefault();
  links[j].focus();
});
list.addEventListener('focusin', (e) => {
  const i = links.indexOf(e.target);
  let fv = false; try { fv = e.target.matches(':focus-visible'); } catch (_) {}
  if (i >= 0 && fv) pluck(i, 0.2, -7);
});
links.forEach((a, i) => a.addEventListener('click', (e) => {
  e.preventDefault();
  links.forEach((b) => b.removeAttribute('aria-current'));
  a.setAttribute('aria-current', 'true');
  pluck(i, 0.5, AMP);
}));

const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } layout(); });
ro.observe(list);
layout();
/* an opening strum, top to bottom, so the still frame has already been played once */
if (!reduce.matches) strings.forEach((s, i) => setTimeout(() => { if (!root.isConnected) return; pluck(i, 0.3 + i * 0.09, i % 2 ? 6 : -6); }, 380 + i * 110));

