.fxh-riso {
  --fxh-riso-paper: oklch(95.5% 0.022 88);
  --fxh-riso-a: oklch(67% 0.23 2);
  --fxh-riso-b: oklch(50% 0.15 252);
  --fxh-riso-c: oklch(88% 0.17 95);
  --fxh-riso-table: oklch(88.5% 0.02 75);
  --fxh-riso-text: oklch(28% 0.03 60);
  --fxh-riso-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  container-name: fxh-riso;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  max-width: 360px;
  margin: 0 auto;
  padding: 14px 14px 10px;
  border-radius: 16px;
  background:
    radial-gradient(120% 80% at 30% 0%, color-mix(in oklch, var(--fxh-riso-table), white 30%), transparent 70%),
    var(--fxh-riso-table);
  color: var(--fxh-riso-text);
  font: 400 12px/1.35 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h3, p) { margin: 0; }
}
.fxh-riso-sheet {
  position: relative;
  isolation: isolate;
  overflow: clip;            /* not a scroll container, so the aspect ratio can still grow to fit */
  aspect-ratio: 1 / .96;
  display: grid;
  grid-template: auto / minmax(0, 1fr);
  border-radius: 3px;
  background: var(--fxh-riso-paper);
  box-shadow: 0 1px 0 oklch(100% 0 0 / .7) inset, 0 16px 30px -14px oklch(30% 0.04 60 / .45), 0 2px 5px oklch(30% 0.04 60 / .18);
  cursor: pointer;
  touch-action: pan-y;
  outline: none;
  &:focus-visible { box-shadow: 0 0 0 3px var(--fxh-riso-paper), 0 0 0 5px var(--fxh-riso-b); }
}

/* three plates, same markup, stacked in one grid cell so they always lay out identically;
   each one only "prints" the parts assigned to its ink */
.fxh-riso-plate {
  grid-area: 1 / 1;
  position: relative;
  display: grid;
  mix-blend-mode: multiply;
  transform-origin: 50% 50%;
  will-change: transform;
}
.fxh-riso-py { --fxh-riso-own: var(--fxh-riso-c); --fxh-riso-k-sun: var(--fxh-riso-c); --fxh-riso-k-dot: var(--fxh-riso-c); }
.fxh-riso-pa { --fxh-riso-own: var(--fxh-riso-a); --fxh-riso-k-head: var(--fxh-riso-a); --fxh-riso-k-lab: var(--fxh-riso-a); --fxh-riso-k-no: var(--fxh-riso-a); --fxh-riso-k-hatch: var(--fxh-riso-a); }
.fxh-riso-pb { --fxh-riso-own: var(--fxh-riso-b); --fxh-riso-k-head: var(--fxh-riso-b); --fxh-riso-k-text: var(--fxh-riso-b); }

.fxh-riso-ink {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto 1fr auto auto;
  grid-template-areas: "top no" "head head" "info info" "foot foot";
  gap: 8px;
  padding: clamp(13px, 5.5cqi, 20px);
}
.fxh-riso-sun, .fxh-riso-hatch {
  position: absolute; top: 24%; right: -13cqi;
  width: 60cqi; aspect-ratio: 1; border-radius: 50%;
}
.fxh-riso-sun { background: var(--fxh-riso-k-sun, transparent); }
.fxh-riso-hatch {
  background: repeating-linear-gradient(-38deg, var(--fxh-riso-k-hatch, transparent) 0 1.6px, transparent 1.6px 6px);
  clip-path: inset(56% 0 0 0);
}
.fxh-riso-dots {
  position: absolute; left: 0; bottom: 0; width: 78%; height: 52%;
  background: radial-gradient(circle, var(--fxh-riso-k-dot, transparent) 0 1.65px, transparent 2.1px) 0 0 / 7px 7px;
  -webkit-mask-image: radial-gradient(115% 100% at 0% 100%, #000 18%, transparent 72%);
  mask-image: radial-gradient(115% 100% at 0% 100%, #000 18%, transparent 72%);
}
.fxh-riso-badge {
  position: absolute; top: 12%; right: 30cqi; width: 30cqi; aspect-ratio: 1;
  fill: var(--fxh-riso-a); font: 800 9.6px system-ui, sans-serif; letter-spacing: .02em;
  animation: fxh-riso-spin 26s linear infinite;
}
@keyframes fxh-riso-spin { to { rotate: 360deg; } }

.fxh-riso-top {
  grid-area: top; align-self: start; position: relative;
  font-size: 10px; font-weight: 750; letter-spacing: .16em; text-transform: uppercase;
  color: var(--fxh-riso-k-text, transparent);
  & span { display: block; font-weight: 500; letter-spacing: .12em; }
}
.fxh-riso-no {
  grid-area: no; position: relative; display: grid; place-items: center; align-content: center;
  width: 46px; aspect-ratio: 1; border-radius: 50%; border: 1.5px solid var(--fxh-riso-k-no, transparent);
  color: var(--fxh-riso-k-no, transparent); font: 800 17px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums;
  rotate: -12deg;
  & span { font: 650 8px/1 system-ui, sans-serif; letter-spacing: .14em; text-transform: uppercase; margin-bottom: 2px; }
}
.fxh-riso-head {
  grid-area: head; align-self: start; position: relative; margin-top: 2px;
  font: 900 clamp(38px, 18.5cqi, 78px)/.84 system-ui, -apple-system, "Segoe UI", sans-serif;
  letter-spacing: -.055em; text-transform: uppercase; text-wrap: balance;
  color: var(--fxh-riso-k-head, transparent);
}
.fxh-riso-info {
  grid-area: info; position: relative; display: flex; gap: clamp(14px, 7cqi, 28px);
  padding-top: 8px; border-top: 1.5px solid var(--fxh-riso-k-text, transparent);
  font-size: clamp(11px, 3.7cqi, 13px); font-weight: 650; line-height: 1.25; font-variant-numeric: tabular-nums;
  color: var(--fxh-riso-k-text, transparent);
}
.fxh-riso-lab {
  display: block; margin-bottom: 3px;
  font-size: 8.5px; font-weight: 700; letter-spacing: .16em; text-transform: uppercase;
  color: var(--fxh-riso-k-lab, transparent);
}
.fxh-riso-foot {
  grid-area: foot; position: relative; padding-right: 22px;
  font-size: 9.5px; font-weight: 600; letter-spacing: .04em; color: var(--fxh-riso-k-text, transparent);
}
.fxh-riso-mark {
  position: absolute; right: 10px; bottom: 10px; width: 14px; height: 14px;
  fill: none; stroke: var(--fxh-riso-own); stroke-width: 1;
}
.fxh-riso-grain {
  position: absolute; inset: 0; width: 100%; height: 100%;
  pointer-events: none; mix-blend-mode: multiply; opacity: .5;
}

.fxh-riso-cap {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  margin-top: 10px;
}
.fxh-riso-stat {
  display: flex; flex-wrap: wrap; gap: 2px 12px;
  font: 500 10.5px/1.3 ui-monospace, Menlo, monospace; letter-spacing: .02em; font-variant-numeric: tabular-nums;
  color: color-mix(in oklch, var(--fxh-riso-text) 72%, var(--fxh-riso-table));
  & b { font-weight: 700; color: var(--fxh-riso-text); }
}
.fxh-riso-pull {
  appearance: none; flex: none; display: inline-flex; align-items: center; gap: 6px;
  height: 30px; padding: 0 11px 0 7px; border: 0; border-radius: 99px; cursor: pointer;
  background: var(--fxh-riso-text); color: var(--fxh-riso-paper);
  font: 650 11.5px/1 system-ui, sans-serif;
  transition: transform .45s var(--fxh-riso-spring), background-color .2s;
  &:hover { background: color-mix(in oklch, var(--fxh-riso-text), var(--fxh-riso-b) 35%); }
  &:active { transform: scale(.95); }
  &:focus-visible { outline: 2px solid var(--fxh-riso-b); outline-offset: 2px; }
  & svg { width: 18px; height: 18px; isolation: isolate; }
  & circle { mix-blend-mode: multiply; }
  & circle:nth-child(1) { fill: var(--fxh-riso-a); }
  & circle:nth-child(2) { fill: var(--fxh-riso-b); }
  & circle:nth-child(3) { fill: var(--fxh-riso-c); }
}

@container fxh-riso (max-width: 290px) {
  .fxh-riso-foot { display: none; }
  .fxh-riso-no { width: 40px; font-size: 15px; }
}

@media (prefers-reduced-motion: reduce) {
  .fxh-riso-badge { animation: none; }
  .fxh-riso-pull { transition: background-color .2s; }
  .fxh-riso-plate { will-change: auto; }
}

js:
const sheet = root.querySelector('.fxh-riso-sheet');
const pullBtn = root.querySelector('.fxh-riso-pull');
const edEl = root.querySelector('.fxh-riso-ed');
const rgEl = root.querySelector('.fxh-riso-rg');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const PX_MM = 0.2646;   /* 1 CSS px at 96 dpi */

/* Each plate answers the pointer's velocity through its own rotation and gain, so a
   swipe fans the inks apart in three directions; a spring pulls them back to a small,
   permanent misregistration that changes with every print, as on a real duplicator. */
const plates = [
  ['.fxh-riso-py', 0.55, -115, 0.5, 1.3],
  ['.fxh-riso-pa', 1.0, 0, 1.5, -0.9],
  ['.fxh-riso-pb', 0.8, 145, -0.9, 0.6]
].map(([sel, g, deg, rx, ry]) => {
  const a = deg * Math.PI / 180;
  return { el: root.querySelector(sel), g, c: Math.cos(a) * g, s: Math.sin(a) * g, rx, ry, x: rx, y: ry, vx: 0, vy: 0, r: 0, vr: 0 };
});
const K = 150, C = 8.5, KR = 120, CR = 8, LIM = 18, RLIM = 4;
let raf = 0, last = 0, lp = null, box = null, ed = 37, rgText = '';

function render() {
  for (const p of plates) p.el.style.transform = 'translate3d(' + p.x.toFixed(2) + 'px,' + p.y.toFixed(2) + 'px,0) rotate(' + p.r.toFixed(3) + 'deg)';
  let m = 0;
  for (let i = 0; i < 3; i++) for (let j = i + 1; j < 3; j++) m = Math.max(m, Math.hypot(plates[i].x - plates[j].x, plates[i].y - plates[j].y));
  const t = (m * PX_MM).toFixed(2);
  if (t !== rgText) { rgText = t; rgEl.textContent = t; }
}
function tick(now) {
  if (!root.isConnected) return;
  raf = 0;
  let dt = Math.min(0.05, (now - last) / 1000); last = now;
  let busy = false;
  while (dt > 0) {
    const h = Math.min(dt, 1 / 120); dt -= h;
    for (const p of plates) {
      p.vx += (-K * (p.x - p.rx) - C * p.vx) * h; p.x += p.vx * h;
      p.vy += (-K * (p.y - p.ry) - C * p.vy) * h; p.y += p.vy * h;
      p.vr += (-KR * p.r - CR * p.vr) * h; p.r += p.vr * h;
      p.x = p.rx + Math.max(-LIM, Math.min(LIM, p.x - p.rx));
      p.y = p.ry + Math.max(-LIM, Math.min(LIM, p.y - p.ry));
      p.r = Math.max(-RLIM, Math.min(RLIM, p.r));
    }
  }
  for (const p of plates) {
    if (Math.abs(p.x - p.rx) + Math.abs(p.y - p.ry) + Math.abs(p.r) > 0.02 || Math.abs(p.vx) + Math.abs(p.vy) + Math.abs(p.vr) > 0.2) busy = true;
  }
  if (!busy) for (const p of plates) { p.x = p.rx; p.y = p.ry; p.r = 0; p.vx = p.vy = p.vr = 0; }
  render();
  if (busy) raf = requestAnimationFrame(tick);
}
function kick() { if (!raf) { last = performance.now(); raf = requestAnimationFrame(tick); } }

/* velocity in px/s, (qx, qy) where it happened, -1..1 from the sheet centre */
function impulse(vx, vy, qx, qy) {
  if (reduce.matches) return;
  for (const p of plates) {
    p.vx += (p.c * vx - p.s * vy) * 0.06;
    p.vy += (p.s * vx + p.c * vy) * 0.06;
    p.vr += (vx * qy - vy * qx) * 0.012 * p.g;
  }
  kick();
}

sheet.addEventListener('pointerenter', () => { box = sheet.getBoundingClientRect(); lp = null; });
sheet.addEventListener('pointermove', (e) => {
  if (!box) box = sheet.getBoundingClientRect();
  const t = e.timeStamp;
  if (lp && t > lp.t) {
    const dt = Math.max(8, Math.min(80, t - lp.t)) / 1000;
    const qx = ((e.clientX - box.left) / box.width) * 2 - 1, qy = ((e.clientY - box.top) / box.height) * 2 - 1;
    impulse((e.clientX - lp.x) / dt, (e.clientY - lp.y) / dt, qx, qy);
  }
  lp = { x: e.clientX, y: e.clientY, t };
});
sheet.addEventListener('pointerleave', () => { lp = null; box = null; });

/* every pull is a new print: fresh misregistration, slightly different ink density */
function pull() {
  if (ed < 120) { ed++; edEl.textContent = ed; }
  const rnd = (a) => (Math.random() * 2 - 1) * a;
  for (const p of plates) {
    p.rx = +rnd(1.8).toFixed(2); p.ry = +rnd(1.8).toFixed(2);
    p.el.style.opacity = (0.84 + Math.random() * 0.14).toFixed(2);
    if (reduce.matches) { p.x = p.rx; p.y = p.ry; }
    else { p.vx += rnd(260); p.vy += rnd(260) - 120; p.vr += rnd(40); }
  }
  if (reduce.matches) { render(); return; }
  if (sheet.animate) sheet.animate([{ transform: 'translateY(-10px) rotate(-.8deg)', opacity: .6 }, { transform: 'none', opacity: 1 }],
    { duration: 620, easing: 'linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1)' });
  kick();
}
sheet.addEventListener('click', pull);
pullBtn.addEventListener('click', pull);
sheet.addEventListener('keydown', (e) => {
  const d = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] }[e.key];
  if (d) { e.preventDefault(); impulse(d[0] * 1500, d[1] * 1500, d[1] * 0.6, -d[0] * 0.6); }
  else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pull(); }
});
render();

css:
.fxh-moon {
  --fxh-moon-sky: oklch(15% 0.012 55);
  --fxh-moon-dot: oklch(93% 0.035 85);
  --fxh-moon-sunc: oklch(82% 0.14 70);
  --fxh-moon-ink: oklch(93% 0.02 85);
  --fxh-moon-muted: color-mix(in oklch, var(--fxh-moon-ink) 55%, var(--fxh-moon-sky));
  --fxh-moon-line: color-mix(in oklch, var(--fxh-moon-ink) 14%, var(--fxh-moon-sky));
  container-name: fxh-moon;
  container-type: inline-size;
  position: relative;
  box-sizing: border-box;
  width: 100%;
  aspect-ratio: 1 / 1.02;
  max-height: 460px;
  display: grid;
