}
.fxh-moon-read { grid-area: read; display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; }
.fxh-moon-pct {
  display: flex; align-items: baseline; gap: 3px; font-variant-numeric: tabular-nums;
  & b { font-size: clamp(30px, 13cqi, 46px); font-weight: 300; letter-spacing: -.045em; line-height: .9; }
  & span { font-size: 12px; color: var(--fxh-moon-muted); }
}
.fxh-moon-name {
  display: grid; justify-items: end; gap: 2px; text-align: right;
  & .fxh-moon-phase { font-size: clamp(13px, 4.6cqi, 15px); font-weight: 600; letter-spacing: -.01em; text-wrap: balance; }
  & .fxh-moon-age { font: 500 10.5px/1.2 ui-monospace, Menlo, monospace; color: var(--fxh-moon-muted); font-variant-numeric: tabular-nums; }
}

