const sky = root.querySelector('.fxh-moon-sky');
const cv = root.querySelector('.fxh-moon-cv');
const sun = root.querySelector('.fxh-moon-sun');
const numEl = root.querySelector('.fxh-moon-num');
const phaseEl = root.querySelector('.fxh-moon-phase');
const ageEl = root.querySelector('.fxh-moon-age');
const ctx = cv.getContext('2d');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const SYN = 29.53, RAD = Math.PI / 180;

/* A halftone moon lit by a movable sun. Dots are precomputed once per size (position,
   surface normal, albedo of the maria); each frame is one dot product per dot and a
   single batched fill. The pointer's distance from the disc maps to the phase angle:
   centre = full, on the limb = quarter, two radii out = new. */
let W = 0, H = 0, R = 0, cx = 0, cy = 0, dots = null, color = '#eee';
const L = [0, 0, 1], T = [0, 0, 1];
let mode = reduce.matches ? 'still' : 'orbit', E = 114, lastInput = 0, raf = 0, last = 0, visible = true, shown = '';

const MARIA = [[-0.45, -0.36, 0.34], [-0.64, 0.06, 0.36], [0.12, -0.33, 0.2], [0.31, -0.04, 0.24],
  [0.68, -0.26, 0.13], [-0.16, 0.4, 0.19], [0.27, 0.31, 0.14], [-0.3, 0.12, 0.12]];
function hash(x, y) { const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453; return s - Math.floor(s); }
function albedo(u, v) {
  let a = 1;
  for (const [mx, my, mr] of MARIA) {
    const d = Math.hypot(u - mx, v - my) / mr;
    if (d < 1.25) a -= 0.36 * Math.max(0, Math.min(1, 1.25 - d));
  }
  const ty = Math.hypot(u + 0.12, v - 0.72);                  /* one bright young crater */
  a += 0.35 * Math.exp(-ty * ty / 0.004);
  a += (hash(u * 40, v * 40) - 0.5) * 0.12;
  return Math.max(0.35, Math.min(1.25, a));
}
function build() {
  const dpr = Math.min(2, devicePixelRatio || 1);
  W = sky.clientWidth; H = sky.clientHeight;
  if (!W || !H) return;
  cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  R = Math.min(W, H) * 0.31; cx = W / 2; cy = H * 0.48;
  const s = Math.max(3.6, Math.min(7, R / 21)), rows = s * 0.866, out = [];
  for (let j = 0, y = cy - R; y <= cy + R; j++, y = cy - R + j * rows) {
    for (let x = cx - R + (j % 2 ? s / 2 : 0); x <= cx + R; x += s) {
      const u = (x - cx) / R, v = (y - cy) / R, q = u * u + v * v;
      if (q > 0.995) continue;
      out.push(x, y, u, v, Math.sqrt(1 - q), albedo(u, v), s * 0.58);
    }
  }
  dots = new Float32Array(out);
  color = getComputedStyle(root).getPropertyValue('--fxh-moon-dot').trim() || '#eee';
  draw();
}
function setFromElongation(e) {           /* orbit: e = 0 new, 90 first quarter, 180 full */
  const a = e * RAD;
  T[0] = Math.sin(a); T[1] = -0.14; T[2] = -Math.cos(a);
  const n = Math.hypot(T[0], T[1], T[2]); T[0] /= n; T[1] /= n; T[2] /= n;
}
function setFromPoint(px, py) {
  const dx = px - cx, dy = py - cy, d = Math.hypot(dx, dy) / R;
  const th = Math.min(2, d) * 90 * RAD, ux = d ? dx / (d * R) : 0, uy = d ? dy / (d * R) : 0;
  T[0] = Math.sin(th) * ux; T[1] = Math.sin(th) * uy; T[2] = Math.cos(th);
}
function draw() {
  if (!dots) return;
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = color;
  ctx.beginPath();
  const lx = L[0], ly = L[1], lz = L[2];
  for (let i = 0; i < dots.length; i += 7) {
    const nl = dots[i + 2] * lx + dots[i + 3] * ly + dots[i + 4] * lz;
    const soft = Math.max(0, Math.min(1, (nl + 0.06) / 0.24));
    const b = soft * (0.22 + 0.78 * Math.max(0, nl)) * dots[i + 5] + 0.035;   /* + earthshine */
    const r = dots[i + 6] * Math.sqrt(Math.min(1, b));
    if (r < 0.3) continue;
    ctx.moveTo(dots[i] + r, dots[i + 1]);
    ctx.arc(dots[i], dots[i + 1], r, 0, 6.2832);
  }
  ctx.fill();
  /* the sun marker sits where the light comes from, dimmed when it is behind the moon */
  const th = Math.acos(Math.max(-1, Math.min(1, lz))) / RAD / 90, pl = Math.hypot(lx, ly) || 1;
  const reach = Math.min(th * R, Math.min(W, H) * 0.45);
  sun.style.transform = 'translate(' + (cx + lx / pl * reach).toFixed(1) + 'px,' + (cy + ly / pl * reach).toFixed(1) + 'px)';
  sun.style.opacity = lz < -0.35 ? '0.35' : lz > 0.6 ? '0.6' : '1';
  readout();
}
function readout() {
  const k = (1 + L[2]) / 2, pct = Math.round(k * 100);
  const el = Math.acos(Math.max(-1, Math.min(1, -L[2]))) / RAD;          /* 0..180 */
  const waxing = L[0] >= 0;
  const age = (waxing ? el : 360 - el) / 360 * SYN;
  let name;
  if (pct <= 2) name = 'New moon';
  else if (pct >= 98) name = 'Full moon';
  else if (pct >= 47 && pct <= 53) name = waxing ? 'First quarter' : 'Last quarter';
  else name = (waxing ? 'Waxing ' : 'Waning ') + (pct < 50 ? 'crescent' : 'gibbous');
  const key = pct + name + age.toFixed(1);
  if (key === shown) return;
  shown = key;
  numEl.textContent = pct;
  phaseEl.textContent = name;
  ageEl.textContent = 'Day ' + age.toFixed(1) + ' of 29.5';
  sky.setAttribute('aria-valuenow', pct);
  sky.setAttribute('aria-valuetext', name + ', ' + pct + '% illuminated');
}
function tick(now) {
  if (!root.isConnected) return;
  raf = 0;
  if (!visible) return;
  const dt = Math.min(0.05, (now - last) / 1000); last = now;
  if (mode === 'orbit' && !reduce.matches) { E = (E + dt * 9) % 360; setFromElongation(E); }
  else if (mode === 'rest' && now - lastInput > 2600 && !reduce.matches) {
    E = ((Math.atan2(L[0], -L[2]) / RAD) + 360) % 360; mode = 'orbit';
  }
  const f = reduce.matches ? 1 : 1 - Math.pow(0.0008, dt);
  let moved = 0;
  for (let i = 0; i < 3; i++) { const d = (T[i] - L[i]) * f; L[i] += d; moved += Math.abs(d); }
  const n = Math.hypot(L[0], L[1], L[2]) || 1; L[0] /= n; L[1] /= n; L[2] /= n;
  const live = !reduce.matches && (mode === 'orbit' || mode === 'rest');
  if (moved > 1e-5 || (mode === 'orbit' && !reduce.matches)) draw();
  /* rAF itself is suspended while the document is hidden; offscreen, the observer stops the loop */
  if (moved > 1e-5 || live) raf = requestAnimationFrame(tick);
}
function kick() { if (!raf && visible) { last = performance.now(); raf = requestAnimationFrame(tick); } }

let box = null;
sky.addEventListener('pointerenter', () => { box = sky.getBoundingClientRect(); sun.style.scale = '1.25'; });
sky.addEventListener('pointermove', (e) => {
  if (!box) box = sky.getBoundingClientRect();
  mode = 'pointer'; setFromPoint(e.clientX - box.left, e.clientY - box.top); kick();
});
sky.addEventListener('pointerdown', (e) => {
  box = sky.getBoundingClientRect();
  mode = 'pointer'; setFromPoint(e.clientX - box.left, e.clientY - box.top); kick();
});
sky.addEventListener('pointerleave', () => { box = null; sun.style.scale = ''; mode = 'rest'; lastInput = performance.now(); kick(); });

/* slider semantics: arrows step the elongation 6 degrees, Home = new, End = full */
sky.addEventListener('keydown', (e) => {
  const cur = ((Math.atan2(L[0], -L[2]) / RAD) + 360) % 360;
  let next = null;
  if (e.key === 'ArrowRight' || e.key === 'ArrowUp') next = cur + 6;
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') next = cur - 6;
  else if (e.key === 'PageUp') next = cur + 30;
  else if (e.key === 'PageDown') next = cur - 30;
  else if (e.key === 'Home') next = 0.5;
  else if (e.key === 'End') next = 180;
  if (next === null) return;
  e.preventDefault();
  E = (next + 360) % 360; setFromElongation(E);
  mode = 'rest'; lastInput = performance.now() + 2000; kick();
});

const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } build(); });
ro.observe(sky);
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  visible = es[es.length - 1].isIntersecting;
  if (visible) kick();
});
io.observe(root);
setFromElongation(E); L[0] = T[0]; L[1] = T[1]; L[2] = T[2];
build();
kick();

