.fxh-index {
  --fxh-index-bg: oklch(21% 0.028 158);
  --fxh-index-ink: oklch(95% 0.016 110);
  --fxh-index-accent: oklch(79% 0.14 52);
  --fxh-index-line: color-mix(in oklch, var(--fxh-index-ink) 13%, var(--fxh-index-bg));
  --fxh-index-muted: color-mix(in oklch, var(--fxh-index-ink) 55%, var(--fxh-index-bg));
  --fxh-index-ease: cubic-bezier(.2, .9, .1, 1);
  --fxh-index-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  container-name: fxh-index;
  container-type: inline-size;
  position: relative;
  overflow: clip;
  box-sizing: border-box;
  width: 100%;
  padding: clamp(14px, 5.5cqi, 22px) clamp(14px, 5.5cqi, 22px) 10px;
  border-radius: 16px;
  background: var(--fxh-index-bg);
  color: var(--fxh-index-ink);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h4, p, ol, dl, dd) { margin: 0; padding: 0; }
}
.fxh-index-head {
  display: flex; justify-content: space-between; gap: 10px; padding-bottom: 10px; white-space: nowrap;
  border-bottom: 1px solid var(--fxh-index-line);
  font: 500 10.5px/1 ui-monospace, Menlo, monospace; letter-spacing: .08em; text-transform: uppercase; color: var(--fxh-index-muted);
  font-variant-numeric: tabular-nums;
}
.fxh-index-studio { color: var(--fxh-index-ink); font-weight: 700; }
.fxh-index-list { list-style: none; }
.fxh-index-row {
  appearance: none; width: 100%; margin: 0; padding: 10px 0 11px;
  display: grid; grid-template-columns: 2.1em minmax(0, 1fr) auto; grid-template-areas: "num name yr" "num kind yr";
  align-items: baseline; column-gap: 4px;
  border: 0; border-bottom: 1px solid var(--fxh-index-line); background: none; color: inherit; font: inherit; text-align: left; cursor: pointer;
  transition: opacity .3s ease-out;
  &:focus-visible { outline: 2px solid var(--fxh-index-accent); outline-offset: -2px; border-radius: 6px; }
}
.fxh-index-num { grid-area: num; align-self: start; padding-top: .45em; font: 500 10.5px/1 ui-monospace, Menlo, monospace; color: var(--fxh-index-muted); font-variant-numeric: tabular-nums; transition: color .25s; }
.fxh-index-name {
  grid-area: name; font-size: clamp(19px, 7.6cqi, 30px); font-weight: 620; line-height: 1.02; letter-spacing: -.035em;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  transition: translate .6s var(--fxh-index-spring), color .25s;
}
.fxh-index-kind { grid-area: kind; margin-top: 2px; font-size: 11.5px; color: var(--fxh-index-muted); transition: translate .6s 25ms var(--fxh-index-spring); }
.fxh-index-yr { grid-area: yr; align-self: center; font: 500 11px/1 ui-monospace, Menlo, monospace; color: var(--fxh-index-muted); font-variant-numeric: tabular-nums; }
.fxh-index-list:has(.fxh-index-row:is(:hover, :focus-visible)) .fxh-index-row:not(:hover, :focus-visible) { opacity: .34; }
.fxh-index-row:is(:hover, :focus-visible) {
  & .fxh-index-name, & .fxh-index-kind { translate: 8px 0; }
  & .fxh-index-num { color: var(--fxh-index-accent); }
}

/* the floating preview: a clipped window onto a vertical reel of all five covers */
.fxh-index-peek {
  position: absolute; left: 0; top: 0; z-index: 3;
  width: clamp(124px, 44cqi, 210px); aspect-ratio: 4 / 3;
  border-radius: 10px; overflow: hidden; pointer-events: none;
  clip-path: inset(50% 50% 50% 50% round 10px); opacity: 0;
  transition: clip-path .55s var(--fxh-index-ease), opacity .25s;
  will-change: transform;
}
.fxh-index.is-peek .fxh-index-peek { clip-path: inset(0 0 0 0 round 10px); opacity: 1; }
.fxh-index-reel {
  height: 100%;
  transform: translateY(calc(var(--fxh-index-k, 0) * -100%));
  transition: transform .75s var(--fxh-index-spring);
}
.fxh-index-art { position: relative; height: 100%; overflow: hidden; container-type: size; }

/* covers, drawn with gradients and type only */
.fxh-index-a0 {
  background:
    radial-gradient(circle at 0 0, oklch(60% 0.15 38) 0 49%, transparent 50%) 0 0 / 22% 29.3%,
    radial-gradient(circle at 100% 100%, oklch(78% 0.13 75) 0 49%, transparent 50%) 0 0 / 22% 29.3%,
    oklch(94% 0.03 85);
}
.fxh-index-wm {
  position: absolute; left: 7cqi; bottom: 8cqb; padding: 2.4cqi 4cqi; border-radius: 99px;
  background: oklch(94% 0.03 85); color: oklch(32% 0.08 38); font-size: 8cqi; font-weight: 750; letter-spacing: -.03em;
}
.fxh-index-a1 { background: oklch(86% 0.17 95); color: oklch(18% 0.01 90); }
.fxh-index-arw { position: absolute; left: 5cqi; top: 6cqb; width: 54cqb; height: 54cqb; fill: none; stroke: currentColor; stroke-width: 2.6; stroke-linecap: square; }
.fxh-index-gate {
  position: absolute; right: 6cqi; top: 7cqb; display: grid; place-items: center; width: 22cqi; aspect-ratio: 1; border-radius: 50%;
  background: oklch(18% 0.01 90); color: oklch(86% 0.17 95); font: 800 7.5cqi/1 system-ui, sans-serif; letter-spacing: -.02em;
}
.fxh-index-band {
  position: absolute; left: 0; right: 0; bottom: 0; padding: 4cqb 6cqi; background: oklch(18% 0.01 90); color: oklch(86% 0.17 95);
  font: 750 7.6cqi/1 system-ui, sans-serif; letter-spacing: -.01em; white-space: nowrap;
  & i { font-style: normal; display: inline-block; margin-inline: 1.5cqi; }
}
.fxh-index-a2 {
  background:
    repeating-radial-gradient(circle at 64% 54%, oklch(30% 0.01 80 / .55) 0 .5px, transparent .8px 3.2cqi),
    radial-gradient(circle at 64% 54%, oklch(77% 0.012 80), oklch(62% 0.014 80));
}
.fxh-index-disc { position: absolute; left: 64%; top: 54%; width: 26cqi; aspect-ratio: 1; translate: -50% -50%; border-radius: 50%; background: radial-gradient(circle, oklch(20% 0.01 80) 0 7%, oklch(58% 0.14 40) 8%); }
.fxh-index-qs { position: absolute; left: 6cqi; top: 7cqb; font: 800 8.2cqi/.9 system-ui, sans-serif; letter-spacing: .02em; text-transform: uppercase; color: oklch(22% 0.01 80); }
.fxh-index-a3 { background: linear-gradient(160deg, oklch(91% 0.07 135), oklch(82% 0.1 140)); }
.fxh-index-phone {
  position: absolute; left: 50%; top: 14cqb; width: 56cqi; height: 100cqb; translate: -50% 0; rotate: -6deg;
  display: grid; align-content: start; gap: 1cqb; padding: 6cqi 6cqi; border-radius: 6cqi 6cqi 0 0;
  background: oklch(99% 0.005 135); color: oklch(26% 0.04 150); box-shadow: 0 2cqi 6cqi oklch(30% 0.06 150 / .25);
  & small { font-size: 4.4cqi; color: oklch(50% 0.03 150); }
  & b { font-size: 8.6cqi; font-weight: 700; letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & svg { width: 100%; height: 20cqb; margin-top: 2cqb; fill: none; stroke: oklch(55% 0.15 145); stroke-width: 2; vector-effect: non-scaling-stroke; }
}
.fxh-index-a4 { background: linear-gradient(170deg, oklch(30% 0.05 35), oklch(19% 0.03 30)); }
.fxh-index-arch {
  position: absolute; left: 50%; bottom: 0; width: 44cqi; height: 76cqb; translate: -50% 0; border-radius: 99cqi 99cqi 0 0;
  background: radial-gradient(70% 45% at 50% 100%, oklch(80% 0.16 60), oklch(56% 0.19 38) 55%, oklch(34% 0.1 35));
  box-shadow: 0 0 0 1.6cqi oklch(24% 0.04 32), 0 0 18cqi oklch(65% 0.18 45 / .35);
}
.fxh-index-se { position: absolute; left: 6cqi; top: 7cqb; font: italic 500 8.5cqi/1 ui-serif, Georgia, serif; color: oklch(88% 0.06 70); letter-spacing: -.01em; }

/* detail sheet: opens out of the preview with a clip-path FLIP; the body staggers in */
.fxh-index-sheet {
  position: absolute; inset: 0; z-index: 5;
  display: grid; grid-template-rows: 44% minmax(0, 1fr);
  background: var(--fxh-index-bg);
  &[hidden] { display: none; }
}
.fxh-index-sheet-art { height: auto; }
.fxh-index-sheet-body { display: grid; align-content: start; gap: 6px; padding: 14px clamp(14px, 5.5cqi, 22px); min-height: 0; overflow: auto; }
.fxh-index-sheet-body > * {
  transition: opacity .45s calc(140ms + var(--i) * 55ms) ease-out, translate .7s calc(140ms + var(--i) * 55ms) var(--fxh-index-spring);
}
@starting-style {
