const stage = root.querySelector('.fxh-tiles-stage');
const cv = root.querySelector('.fxh-tiles-cv');
const ctx = cv.getContext('2d');
const radios = [...root.querySelectorAll('.fxh-tiles-seg [role="radio"]')];
const reduce = matchMedia('(prefers-reduced-motion: reduce)');

/* Two scenes are painted once per size into offscreen canvases; the mosaic is a grid of
   springs, each tile drawn as a slice of whichever face its angle shows, foreshortened by
   |cos a| along the axis the pointer was travelling, lifted and shaded mid-turn. */
const faces = [document.createElement('canvas'), document.createElement('canvas')];
let W = 0, H = 0, dpr = 1, cols = 0, rows = 0, tw = 0, th = 0, tiles = [], rest = 0;
let raf = 0, last = 0, visible = true, lastInput = 0, ptr = null, pv = { x: 0, y: 0 }, prevPtr = null;
