  if ('letterSpacing' in g) g.letterSpacing = '-0.04em';
  g.font = '800 ' + fs.toFixed(1) + 'px system-ui, -apple-system, "Segoe UI", sans-serif';
  g.fillText(big, pad - fs * 0.03, pad + fs * 0.78);
  if ('letterSpacing' in g) g.letterSpacing = '0.14em';
  const ss = Math.max(9, fs * 0.15);
  g.font = '700 ' + ss.toFixed(1) + 'px system-ui, -apple-system, "Segoe UI", sans-serif';
  g.fillText(small, pad, pad + fs * 0.78 + ss * 1.9);
