   'dusk-top', 'dusk-mid', 'dusk-low', 'dusk-moon', 'dusk-hill', 'dusk-hill2', 'dusk-ink', 'frame', 'accent']
    .forEach((n) => { P[n] = col('--fxh-tiles-' + n, '#888'); });
