    if (t.a === 0 || t.a === 180) slice(t, t.a === 0 ? 0 : 1, t.x, t.y, tw, th);
    else moving.push(t);
  }
  /* a faint grout line keeps the mosaic legible at rest without cutting the picture up */
  ctx.strokeStyle = 'rgba(0,0,0,.13)'; ctx.lineWidth = 1 / dpr;
  ctx.beginPath();
  for (let c = 1; c < cols; c++) { ctx.moveTo(c * tw, 0); ctx.lineTo(c * tw, H); }
  for (let r = 1; r < rows; r++) { ctx.moveTo(0, r * th); ctx.lineTo(W, r * th); }
  ctx.stroke();
  /* a turning tile leaves a dark hole in its cell and is drawn above its neighbours */
  ctx.fillStyle = PAL ? PAL.frame : '#222';
  for (const t of moving) ctx.fillRect(t.x, t.y, tw, th);
  for (const t of moving) {
    const rad = t.a * Math.PI / 180, cs = Math.cos(rad), s = Math.abs(cs), lift = 1 + 0.18 * Math.abs(Math.sin(rad));
    const w = tw * lift, h = th * lift;
    const dw = t.axis ? w : Math.max(0.5, w * s), dh = t.axis ? Math.max(0.5, h * s) : h;
    const x = t.cx - dw / 2, y = t.cy - dh / 2;
    ctx.fillStyle = 'rgba(0,0,0,.3)'; ctx.fillRect(x + 2, y + 4, dw, dh);
    slice(t, cs >= 0 ? 0 : 1, x, y, dw, dh);
    ctx.fillStyle = 'rgba(0,0,0,' + ((1 - s) * 0.55).toFixed(3) + ')'; ctx.fillRect(x, y, dw, dh);
  }
  if (cur && kbd && document.activeElement === stage) {
    ctx.strokeStyle = PAL ? PAL.accent : '#fc6'; ctx.lineWidth = 2;
    ctx.strokeRect(cur.c * tw + 1, cur.r * th + 1, tw - 2, th - 2);
  }
}
function flip(t, hold, axis) {
  const other = (1 - rest) * 180;
  if (t.to !== other) { t.to = other; t.axis = axis; }
  t.until = Math.max(t.until, performance.now() + hold);
  if (reduce.matches) { t.a = t.to; t.v = 0; dirty = true; }
}
function wave(ox, oy, side, hold) {
  const now = performance.now();
  for (const t of tiles) {
    const dx = t.cx - ox, dy = t.cy - oy, d = Math.hypot(dx, dy);
    t.at = now + (reduce.matches ? 0 : d * 1.7); t.pend = side * 180; t.pax = Math.abs(dx) > Math.abs(dy) ? 0 : 1;
    t.until = hold ? t.at + hold : 0;
  }
