}
function tick(now) {
  if (!root.isConnected) return;
  raf = 0;
  if (!visible) return;
  const dt = Math.min(0.034, Math.max(0.001, (now - last) / 1000)); last = now;
  if (ptr) {
    const r = stage.getBoundingClientRect(), px = ptr.x - r.left, py = ptr.y - r.top;
    if (prevPtr) { pv.x = pv.x * 0.6 + (px - prevPtr.x) * 0.4; pv.y = pv.y * 0.6 + (py - prevPtr.y) * 0.4; }
    prevPtr = { x: px, y: py };
    const rr = Math.max(tw, th) * 1.3, axis = Math.abs(pv.x) >= Math.abs(pv.y) ? 0 : 1;
    for (const t of tiles) if (Math.hypot(t.cx - px, t.cy - py) < rr) flip(t, 620 + Math.random() * 260, axis);
  }
  let busy = !!ptr;
  for (const t of tiles) {
    if (t.at && now >= t.at) { t.to = t.pend; t.axis = t.pax; t.at = 0; if (reduce.matches) { t.a = t.to; dirty = true; } }
    if (t.until && !t.at && now >= t.until) { t.until = 0; t.to = rest * 180; if (reduce.matches) { t.a = t.to; dirty = true; } }
    if (t.at || t.until) busy = true;
    if (t.a !== t.to || t.v !== 0) {
      t.v += (K * (t.to - t.a) - C * t.v) * dt; t.a += t.v * dt;
      if (Math.abs(t.to - t.a) < 0.3 && Math.abs(t.v) < 3) { t.a = t.to; t.v = 0; }
      busy = true; dirty = true;
    }
  }
  draw();
  if (busy) raf = requestAnimationFrame(tick);
}
function kick() { if (!raf && visible) { last = performance.now(); raf = requestAnimationFrame(tick); } }

stage.addEventListener('pointermove', (e) => { kbd = false; ptr = { x: e.clientX, y: e.clientY }; lastInput = performance.now(); kick(); });
stage.addEventListener('pointerdown', (e) => {
  const r = stage.getBoundingClientRect();
  lastInput = performance.now(); wave(e.clientX - r.left, e.clientY - r.top, 1 - rest, 900);
});
stage.addEventListener('pointerleave', () => { ptr = null; prevPtr = null; });

/* keyboard: arrows drive a tile cursor that flips what it lands on; Space or Enter sweeps */
stage.addEventListener('keydown', (e) => {
  const d = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] }[e.key];
  if (!cur) cur = { c: Math.floor(cols / 2), r: Math.floor(rows / 2) };
  kbd = true; lastInput = performance.now();
  if (d) {
    e.preventDefault();
    cur.c = Math.max(0, Math.min(cols - 1, cur.c + d[0])); cur.r = Math.max(0, Math.min(rows - 1, cur.r + d[1]));
    const t = tiles[cur.r * cols + cur.c]; if (t) flip(t, 900, d[0] ? 0 : 1);
    dirty = true; kick();
  } else if (e.key === ' ' || e.key === 'Enter') {
    e.preventDefault();
    wave((cur.c + 0.5) * tw, (cur.r + 0.5) * th, 1 - rest, 900);
  }
});
stage.addEventListener('blur', () => { dirty = true; draw(); });

function setRest(side, focus) {
  if (side === rest) return;
  rest = side;
  radios.forEach((b) => { const on = +b.dataset.side === side; b.setAttribute('aria-checked', String(on)); b.tabIndex = on ? 0 : -1; if (on && focus) b.focus(); });
  lastInput = performance.now();
  wave(side ? W : 0, side ? 0 : H, side, 0);
}
radios.forEach((b) => {
  b.addEventListener('click', () => setRest(+b.dataset.side, false));
  b.addEventListener('keydown', (e) => {
    if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) { e.preventDefault(); setRest(1 - rest, true); }
  });
});

/* at rest a few tiles turn over on their own, now and then */
function idle() {
  if (!root.isConnected) return;
  if (visible && !document.hidden && !reduce.matches && tiles.length && performance.now() - lastInput > 3200) {
    const t = tiles[Math.floor(Math.random() * tiles.length)], ax = Math.random() < 0.5 ? 0 : 1;
    [[0, 0], [1, 0], [0, 1]].forEach(([dc, dr], k) => {
      const n = tiles[(t.r + dr) * cols + t.c + dc];
      if (n && n.c >= t.c && n.r < rows) setTimeout(() => { if (!root.isConnected) return; flip(n, 700, ax); kick(); }, k * 90);
    });
  }
  idleT = setTimeout(idle, 2000 + Math.random() * 1600);
}

const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } build(); });
ro.observe(stage);
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  visible = es[es.length - 1].isIntersecting;
  if (visible) { dirty = true; kick(); }
});
io.observe(root);
build();
/* an opening sweep so the idea reads in the first second */
setTimeout(() => { if (!root.isConnected || reduce.matches) return; wave(0, 0, 1, 700); }, 650);
idleT = setTimeout(idle, 4200);

css:
.fxh-weight {
  --fxh-weight-bg: oklch(27% 0.085 22);
  --fxh-weight-ink: oklch(93% 0.03 75);
  --fxh-weight-accent: oklch(84% 0.12 72);
  --fxh-weight-line: color-mix(in oklch, var(--fxh-weight-ink) 16%, var(--fxh-weight-bg));
  --fxh-weight-muted: color-mix(in oklch, var(--fxh-weight-ink) 58%, var(--fxh-weight-bg));
  --fxh-weight-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  container-name: fxh-weight;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  display: grid;
  grid-template-areas: "meta" "type" "ctrl";
  gap: clamp(12px, 4.5cqi, 20px);
  padding: clamp(16px, 5.5cqi, 24px);
  border-radius: 18px;
  background:
    radial-gradient(90% 70% at 85% 0%, color-mix(in oklch, var(--fxh-weight-accent) 12%, transparent), transparent 70%),
    var(--fxh-weight-bg);
  color: var(--fxh-weight-ink);
  font: 400 12.5px/1.35 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  accent-color: var(--fxh-weight-accent);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(p) { margin: 0; }
}
.fxh-weight-meta { grid-area: meta; display: flex; justify-content: space-between; align-items: baseline; gap: 10px; }
.fxh-weight-kick {
  font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase;
  & span { display: block; margin-top: 3px; font-weight: 500; letter-spacing: .04em; text-transform: none; color: var(--fxh-weight-muted); }
}
.fxh-weight-read {
  flex: none; font: 500 11px/1 ui-monospace, Menlo, monospace; color: var(--fxh-weight-muted);
  & b { display: inline-block; min-width: 3ch; text-align: right; color: var(--fxh-weight-accent); font-weight: 600; font-variant-numeric: tabular-nums; }
}

/* each letter reads one custom property; weight, colour and lift are all derived in CSS */
.fxh-weight-type {
  grid-area: type;
  position: relative;
  margin: 0;
  font-size: clamp(34px, 15.5cqi, 84px);
  line-height: .96;
  letter-spacing: -.035em;
  cursor: crosshair;
  outline: none;
  touch-action: none;
  &:focus-visible { box-shadow: 0 0 0 2px var(--fxh-weight-bg), 0 0 0 4px var(--fxh-weight-accent); border-radius: 6px; }
}
.fxh-weight-line { display: block; white-space: nowrap; padding-bottom: .04em; border-bottom: 1px solid var(--fxh-weight-line); }
.fxh-weight-word { white-space: nowrap; }
.fxh-weight-l {
  --fxh-weight-g: 0;
  display: inline-block;
  font-weight: calc(260 + var(--fxh-weight-g) * 640);
  color: color-mix(in oklch, var(--fxh-weight-accent) calc(var(--fxh-weight-g) * 100%), var(--fxh-weight-ink));
  translate: 0 calc(var(--fxh-weight-g) * -.05em);
}
.fxh-weight.is-inv .fxh-weight-l { font-weight: calc(900 - var(--fxh-weight-g) * 640); }

.fxh-weight-ctrl { grid-area: ctrl; display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.fxh-weight-field {
  display: grid; grid-template-columns: auto minmax(70px, 1fr) 6ch; align-items: center; gap: 10px; flex: 1 1 180px;
  font-size: 11.5px; color: var(--fxh-weight-muted);
  & input { width: 100%; margin: 0; }
  & input:focus-visible { outline: 2px solid var(--fxh-weight-accent); outline-offset: 3px; border-radius: 4px; }
  & output { font: 500 11px/1 ui-monospace, Menlo, monospace; color: var(--fxh-weight-ink); font-variant-numeric: tabular-nums; text-align: right; }
}
.fxh-weight-inv {
  appearance: none; display: inline-flex; align-items: center; gap: 7px; height: 30px; padding: 0 12px 0 9px;
  border: 1px solid var(--fxh-weight-line); border-radius: 99px; background: none; cursor: pointer;
  color: var(--fxh-weight-ink); font: 600 12px/1 system-ui, sans-serif;
  transition: background-color .25s, color .25s, border-color .25s;
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.6; transition: rotate .6s var(--fxh-weight-spring); }
  & path { fill: currentColor; stroke: none; }
  &:hover { border-color: color-mix(in oklch, var(--fxh-weight-accent) 60%, var(--fxh-weight-line)); }
  &:focus-visible { outline: 2px solid var(--fxh-weight-accent); outline-offset: 2px; }
  &[aria-pressed="true"] { background: var(--fxh-weight-accent); border-color: var(--fxh-weight-accent); color: var(--fxh-weight-bg); & svg { rotate: 180deg; } }
}

@media (prefers-reduced-motion: reduce) {
  .fxh-weight-l { translate: none; }
  .fxh-weight-inv svg { transition: none; }
}

