const type = root.querySelector('.fxh-weight-type');
const letters = [...root.querySelectorAll('.fxh-weight-l')];
const range = root.querySelector('.fxh-weight-field input');
const rangeOut = root.querySelector('.fxh-weight-field output');
const inv = root.querySelector('.fxh-weight-inv');
const readB = root.querySelector('.fxh-weight-read b');
const reduce = matchMedia('(prefers-reduced-motion: reduce)');

/* A virtual focus point drifts on a Lissajous path at rest and eases onto the pointer (or
   the keyboard cursor) when there is one. Each letter's influence is a Gaussian of its
   distance; the script writes one number per letter and only when it changed. Centres are
   measured on resize, never inside the loop. */
let centers = [], TW = 1, TH = 1, BX = [0, 1], BY = [0, 1], sigma = 84 * 0.4, inverted = false;
const prev = new Float32Array(letters.length).fill(-1);
let vx = 0, vy = 0, tx = 0, ty = 0, mode = 'idle', keyI = 0, lastInput = 0, raf = 0, visible = true, t0 = performance.now();

function measure() {
  centers = letters.map((l) => [l.offsetLeft + l.offsetWidth / 2, l.offsetTop + l.offsetHeight * 0.55]);
  TW = type.clientWidth; TH = type.clientHeight;
  const xs = centers.map((c) => c[0]), ys = centers.map((c) => c[1]);
  BX = [Math.min(...xs), Math.max(...xs)]; BY = [Math.min(...ys), Math.max(...ys)];
}
function apply() {
  const s2 = 2 * sigma * sigma;
  let best = 0, bi = 0;
  for (let i = 0; i < letters.length; i++) {
    const c = centers[i]; if (!c) continue;
    const dx = c[0] - vx, dy = (c[1] - vy) * 1.2;
    const g = Math.exp(-(dx * dx + dy * dy) / s2);
    if (g > best) { best = g; bi = i; }
    if (Math.abs(g - prev[i]) > 0.004) { prev[i] = g; letters[i].style.setProperty('--fxh-weight-g', g.toFixed(3)); }
  }
  const w = Math.round(inverted ? 900 - best * 640 : 260 + best * 640);
  if (readB.textContent !== String(w)) readB.textContent = w;
  return [bi, w];
}
function announce() {
  const c = centers[keyI]; if (!c) return;
  const [, w] = apply();
  type.setAttribute('aria-valuenow', keyI + 1);
  type.setAttribute('aria-valuetext', letters[keyI].textContent + ', weight ' + w);
}
function tick(now) {
  if (!root.isConnected) return;
  raf = 0;
  if (!visible) return;
  if (mode !== 'idle' && mode !== 'pointer' && now - lastInput > 3500) mode = 'idle';
  if (mode === 'idle') {
    if (reduce.matches) { apply(); return; }
    const t = (now - t0) / 1000;
    /* stay over the letters themselves, not the empty right side of the block */
    tx = BX[0] + (BX[1] - BX[0]) * (0.5 + 0.5 * Math.sin(t * 0.62));
    ty = BY[0] + (BY[1] - BY[0]) * (0.5 + 0.5 * Math.sin(t * 1.04 + 1.1));
  }
  const k = reduce.matches ? 1 : mode === 'idle' ? 0.06 : 0.2;
  vx += (tx - vx) * k; vy += (ty - vy) * k;
  apply();
  const settled = Math.abs(tx - vx) + Math.abs(ty - vy) < 0.3;
  /* idle drifts forever (while visible); after a key or a pointer leave it waits to drift again */
  const live = !reduce.matches && mode !== 'pointer';
  if (!settled || live) raf = requestAnimationFrame(tick);
}
function kick() { if (!raf && visible) raf = requestAnimationFrame(tick); }

let box = null;
type.addEventListener('pointerenter', () => { box = type.getBoundingClientRect(); });
type.addEventListener('pointermove', (e) => {
  if (!box) box = type.getBoundingClientRect();
  mode = 'pointer'; tx = e.clientX - box.left; ty = e.clientY - box.top; kick();
});
type.addEventListener('pointerleave', () => { box = null; mode = 'rest'; lastInput = performance.now(); kick(); });

/* keyboard: left/right step through letters, up/down jump to the nearest letter on the next line */
type.addEventListener('keydown', (e) => {
  const n = letters.length;
  let j = -1;
  if (e.key === 'ArrowRight') j = Math.min(n - 1, keyI + 1);
  else if (e.key === 'ArrowLeft') j = Math.max(0, keyI - 1);
  else if (e.key === 'Home') j = 0;
  else if (e.key === 'End') j = n - 1;
  else if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    const c = centers[keyI], dir = e.key === 'ArrowDown' ? 1 : -1;
    let bd = 1e9;
    centers.forEach((d, i) => {
      if ((d[1] - c[1]) * dir < 4) return;
      const score = Math.abs(d[1] - c[1]) * 4 + Math.abs(d[0] - c[0]);
      if (score < bd) { bd = score; j = i; }
    });
    if (j < 0) j = keyI;
  }
  if (j < 0) return;
  e.preventDefault();
  keyI = j; mode = 'key'; lastInput = performance.now();
  tx = centers[j][0]; ty = centers[j][1];
  kick(); announce();
});
type.addEventListener('focus', () => {
  let fv = false; try { fv = type.matches(':focus-visible'); } catch (_) {}
  if (!fv || !centers[keyI]) return;
  mode = 'key'; lastInput = performance.now(); tx = centers[keyI][0]; ty = centers[keyI][1]; kick(); announce();
});

range.addEventListener('input', () => {
  sigma = +range.value * 0.4;
  rangeOut.textContent = range.value + ' px';
  apply();
});
inv.addEventListener('click', () => {
  inverted = !inverted;
  inv.setAttribute('aria-pressed', String(inverted));
  root.classList.toggle('is-inv', inverted);
  requestAnimationFrame(() => { if (!root.isConnected) return; measure(); apply(); });
});

const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } measure(); apply(); });
ro.observe(type);
const io = new IntersectionObserver((es) => {
  if (!root.isConnected) { io.disconnect(); return; }
  visible = es[es.length - 1].isIntersecting;
  if (visible) kick();
});
io.observe(root);
measure();
vx = tx = TW * 0.18; vy = ty = TH * 0.2;
apply();
kick();

css:
.fxh-trails {
  --fxh-trails-bg: oklch(97% 0.008 95);
  --fxh-trails-ink: oklch(24% 0.02 150);
  --fxh-trails-accent: oklch(52% 0.12 165);
  --fxh-trails-line: color-mix(in oklch, var(--fxh-trails-ink) 14%, var(--fxh-trails-bg));
  --fxh-trails-muted: color-mix(in oklch, var(--fxh-trails-ink) 60%, var(--fxh-trails-bg));
  --fxh-trails-ease: cubic-bezier(.2, .8, .2, 1);
  --fxh-trails-spring: linear(0, .006, .025 2.8%, .101 6.1%, .539 18.9%, .721 25.3%, .849 31.5%, .937 38.1%, .968 41.8%, .991 45.7%, 1.006 50.1%, 1.015 55%, 1.017 63.9%, 1.001 85.9%, 1);
  container-name: fxh-trails;
  container-type: inline-size;
  box-sizing: border-box;
  width: 100%;
  padding: clamp(16px, 3cqi, 28px);
  border-radius: 20px;
  background: var(--fxh-trails-bg);
  color: var(--fxh-trails-ink);
  font: 400 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h3, h4, p, dl, dd, figure) { margin: 0; }
}
.fxh-trails-head { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: 14px 28px; margin-bottom: clamp(14px, 2.2cqi, 22px); }
.fxh-trails-kick { font-size: 10.5px; font-weight: 650; letter-spacing: .14em; text-transform: uppercase; color: var(--fxh-trails-accent); }
.fxh-trails-title { margin-top: 6px; font-size: clamp(22px, 3.6cqi, 36px); font-weight: 720; line-height: 1.02; letter-spacing: -.035em; text-wrap: balance; }
.fxh-trails-sum {
  display: flex; gap: clamp(14px, 2.6cqi, 30px);
  & div { display: grid; gap: 3px; }
  & dt { font-size: 10px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: var(--fxh-trails-muted); }
  & dd { font-size: clamp(16px, 2cqi, 21px); font-weight: 650; letter-spacing: -.02em; font-variant-numeric: tabular-nums; white-space: nowrap; }
}

/* row mode: panels share the rail; the open one takes seven shares of the free space */
.fxh-trails-rail { display: flex; gap: 8px; height: clamp(300px, 30cqi, 360px); }
.fxh-trails-p {
  position: relative;
  flex: 1 1 0;
  min-width: 0;
  overflow: hidden;
  border-radius: 16px;
  background:
    repeating-radial-gradient(ellipse 150% 95% at var(--fxh-trails-cx, 30%) 112%,
      transparent 0 13px, color-mix(in oklch, var(--fxh-trails-ink) 9%, transparent) 13px 14px),
    var(--fxh-trails-tint, oklch(88% 0.04 150));
  transition: flex-grow .8s var(--fxh-trails-spring), opacity .5s calc(var(--i) * 70ms) ease-out, translate .7s calc(var(--i) * 70ms) var(--fxh-trails-spring);
  &.is-open { flex-grow: 7; }
}
@starting-style {
  .fxh-trails .fxh-trails-p { opacity: 0; translate: 0 18px; }
}
.fxh-trails-tab {
  position: absolute; inset: 0; z-index: 1;
  appearance: none; margin: 0; padding: 16px 14px; border: 0; background: none; cursor: pointer;
  display: grid; grid-template-rows: auto minmax(0, 1fr) auto; justify-items: start; text-align: left;
  color: inherit; font: inherit;
  &:focus-visible { outline: 2px solid var(--fxh-trails-ink); outline-offset: -5px; border-radius: 16px; }
}
.fxh-trails-no { font: 600 11px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
.fxh-trails-vname {
  align-self: end; writing-mode: vertical-rl; rotate: 180deg; white-space: nowrap;
  font-size: clamp(15px, 1.7cqi, 18px); font-weight: 650; letter-spacing: -.01em;
  transition: opacity .3s, translate .5s var(--fxh-trails-ease);
}
