/* narrow containers: the rail turns into a vertical accordion that opens with a 0fr to 1fr row */
@container fxh-trails (max-width: 760px) {
  .fxh-trails-head { grid-template-columns: minmax(0, 1fr); }
  .fxh-trails-sum { flex-wrap: wrap; gap: 10px 20px; }
  .fxh-trails-rail { flex-direction: column; height: auto; gap: 6px; }
  .fxh-trails-p {
