    transition: grid-template-rows .65s var(--fxh-trails-spring), opacity .5s calc(var(--i) * 70ms) ease-out, translate .7s calc(var(--i) * 70ms) var(--fxh-trails-spring);
    &.is-open { grid-template-rows: auto 1fr; }
  }
