  .fxh-trails-body { position: relative; min-width: 0; min-height: 0; overflow: hidden; }
  .fxh-trails-in { height: auto; grid-template-rows: none; padding: 0 14px 14px; }
  .fxh-trails-name { display: none; }
  .fxh-trails-stats { gap: 14px; }
  .fxh-trails-prof { grid-template-rows: 84px auto; }
}

@media (prefers-reduced-motion: reduce) {
  .fxh-trails-p { transition: none; }
  .fxh-trails-in > *, .fxh-trails-p.is-open .fxh-trails-in > * { transition: opacity .2s; translate: none; }
  .fxh-trails-plot svg, .fxh-trails-p.is-open .fxh-trails-plot svg { transition: none; clip-path: none; }
  .fxh-trails-vname { transition: opacity .2s; }
}

