const VMAX = 330;   /* metres at the top of every profile: one scale for all five */
const panels = [...root.querySelectorAll('.fxh-trails-p')];
const tabs = panels.map((p) => p.querySelector('.fxh-trails-tab'));
const rail = root.querySelector('.fxh-trails-rail');
const uid = Math.random().toString(36).slice(2, 7);
let pinned = 0, hot = -1, enterT = 0, leaveT = 0;

panels.forEach((p, i) => {
  const body = p.querySelector('.fxh-trails-body');
  body.id = 'fxh-trails-b' + i + uid;
  tabs[i].setAttribute('aria-controls', body.id);
});
/* read the layout the container query actually chose, so JS and CSS can never disagree */
const wide = () => getComputedStyle(rail).flexDirection === 'row' && matchMedia('(hover: hover)').matches;

/* hover previews (with a short intent delay so sweeping across the rail does not
   cascade), click or keyboard pins; the open panel is whichever is hot, else pinned */
function render() {
  const open = hot >= 0 ? hot : pinned;
  panels.forEach((p, i) => {
    p.classList.toggle('is-open', i === open);
    tabs[i].setAttribute('aria-expanded', String(i === open));
  });
}
panels.forEach((p, i) => {
  p.addEventListener('pointerenter', (e) => {
    if (e.pointerType === 'touch' || !wide()) return;
    clearTimeout(leaveT); clearTimeout(enterT);
    enterT = setTimeout(() => { if (!root.isConnected) return; hot = i; render(); }, 90);
  });
  /* in row mode the open body covers its tab: clicking it pins the preview */
  p.querySelector('.fxh-trails-body').addEventListener('click', () => {
    if (!wide() || pinned === i) return;
    pinned = i; render();
  });
  tabs[i].addEventListener('click', () => {
    if (!wide() && pinned === i && hot < 0) pinned = -1; else pinned = i;
    hot = -1; render();
  });
  tabs[i].addEventListener('keydown', (e) => {
    const n = tabs.length;
    const j = (e.key === 'ArrowRight' || e.key === 'ArrowDown') ? (i + 1) % n
      : (e.key === 'ArrowLeft' || e.key === 'ArrowUp') ? (i - 1 + n) % n
      : e.key === 'Home' ? 0 : e.key === 'End' ? n - 1 : -1;
    if (j < 0) return;
    e.preventDefault(); hot = -1; pinned = j; render(); tabs[j].focus();
  });
});
rail.addEventListener('pointerleave', () => {
  clearTimeout(enterT);
  leaveT = setTimeout(() => { if (!root.isConnected) return; hot = -1; render(); }, 160);
});

/* elevation scrubber: pointer or arrow keys, readout from the same samples as the path */
root.querySelectorAll('.fxh-trails-plot').forEach((plot) => {
  const E = plot.dataset.e.split(',').map(Number), km = +plot.dataset.km, n = E.length;
  const cur = plot.querySelector('.fxh-trails-cur');
  const out = plot.parentElement.querySelector('.fxh-trails-out');
  let k = 0;
  function show(i) {
    k = Math.max(0, Math.min(n - 1, i));
    const f = k / (n - 1), d = (km * f).toFixed(1), e = E[k];
    cur.style.transform = 'translateX(' + (f * plot.clientWidth).toFixed(1) + 'px)';
    cur.style.setProperty('--fxh-trails-y', ((76 - e / VMAX * 68) / 80 * 100).toFixed(2) + '%');
    out.textContent = 'km ' + d + ' · ' + e + ' m';
    plot.setAttribute('aria-valuenow', d);
    plot.setAttribute('aria-valuetext', 'km ' + d + ', ' + e + ' m');
  }
  plot.addEventListener('pointermove', (e) => {
    const r = plot.getBoundingClientRect();
    plot.classList.add('is-scrub');
    show(Math.round((e.clientX - r.left) / r.width * (n - 1)));
  });
  plot.addEventListener('pointerleave', () => plot.classList.remove('is-scrub'));
  plot.addEventListener('focus', () => { plot.classList.add('is-scrub'); show(k); });
  plot.addEventListener('blur', () => plot.classList.remove('is-scrub'));
  plot.addEventListener('keydown', (e) => {
    const step = e.shiftKey ? 6 : 1;
    const j = e.key === 'ArrowRight' ? k + step : e.key === 'ArrowLeft' ? k - step : e.key === 'Home' ? 0 : e.key === 'End' ? n - 1 : null;
    if (j === null) return;
    e.preventDefault(); show(j);
  });
});
render();
